import{_ as o,o as r,c as t,a2 as l}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"中层设定","description":"","frontmatter":{},"headers":[],"relativePath":"中层/index.md","filePath":"中层/index.md","lastUpdated":null}'),e={name:"中层/index.md"};function i(n,a,s,h,u,d){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="中层设定" tabindex="-1">中层设定 <a class="header-anchor" href="#中层设定" aria-label="Permalink to &quot;中层设定&quot;">​</a></h1><h2 id="概念诠释" tabindex="-1">概念诠释 <a class="header-anchor" href="#概念诠释" aria-label="Permalink to &quot;概念诠释&quot;">​</a></h2><p>中层设定是神造物世界观中的<strong>中间认知层面</strong>，位于表层福瑞世界的直观认知与底层神权体系的抽象概念之间。这一层面揭示了表层世界所不知晓的真相，但又不会直接触及世界观最底层的核心逻辑。</p><p>中层设定可以被理解为&quot;世界背后的真相&quot;——福瑞种族生活在一个精心设计的表象之下，而中层设定则揭示了这一表象背后的机制、历史、技术和深层关联。</p><h2 id="定位与特点" tabindex="-1">定位与特点 <a class="header-anchor" href="#定位与特点" aria-label="Permalink to &quot;定位与特点&quot;">​</a></h2><p><strong>核心定位：</strong></p><ul><li><strong>桥梁作用</strong>：连接表层现象与底层逻辑的桥梁</li><li><strong>真相揭示</strong>：揭示表层福瑞世界无法认知的深层事实</li><li><strong>认知过渡</strong>：帮助理解从表象到本质的认知过渡</li></ul><p><strong>主要特点：</strong></p><ul><li><strong>解释表象</strong>：既有福瑞世界可观察的部分事实，又包含他们无法理解的深层机制</li><li><strong>技术内涵</strong>：大量涉及前传、间章时期遗留的技术和设施</li><li><strong>历史真相</strong>：揭示共同体时期、黑暗时代等历史事件的真实背景</li><li><strong>角色动机</strong>：展现神明、关键人物的真实意图和计划</li></ul><h2 id="主要内容领域" tabindex="-1">主要内容领域 <a class="header-anchor" href="#主要内容领域" aria-label="Permalink to &quot;主要内容领域&quot;">​</a></h2><p>中层设定主要涵盖以下几个核心领域：</p><h3 id="一、世界真相" tabindex="-1">一、世界真相 <a class="header-anchor" href="#一、世界真相" aria-label="Permalink to &quot;一、世界真相&quot;">​</a></h3><h4 id="_1-历代三神谱系" tabindex="-1">1. 历代三神谱系 <a class="header-anchor" href="#_1-历代三神谱系" aria-label="Permalink to &quot;1. 历代三神谱系&quot;">​</a></h4><p>提供神权传承脉络和历代神明的基本信息索引，建议作为中层阅读的起点。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./世界/历代三神">历代三神</a></p></blockquote><h4 id="_2-地脉与魔法系统" tabindex="-1">2. 地脉与魔法系统 <a class="header-anchor" href="#_2-地脉与魔法系统" aria-label="Permalink to &quot;2. 地脉与魔法系统&quot;">​</a></h4><p>揭示魔法力量的真正来源、地脉的本质以及法师体系的深层机制</p><blockquote><p><strong>详细内容参见</strong>：<a href="./世界/地脉与魔法">地脉与魔法</a></p></blockquote><h4 id="_3-神机谋划与布局" tabindex="-1">3. 神机谋划与布局 <a class="header-anchor" href="#_3-神机谋划与布局" aria-label="Permalink to &quot;3. 神机谋划与布局&quot;">​</a></h4><p>展现神机作为幕后掌控者的完整计划、太空战略和对世界的时间线掌控</p><blockquote><p><strong>详细内容参见</strong>：<a href="./世界/神机谋划">神机谋划</a></p></blockquote><h4 id="_4-太空巨构与设施" tabindex="-1">4. 太空巨构与设施 <a class="header-anchor" href="#_4-太空巨构与设施" aria-label="Permalink to &quot;4. 太空巨构与设施&quot;">​</a></h4><p>描述地球外的巨型构造物（银河之眼、克隆仓库、月球平台等）及其战略意义</p><blockquote><p><strong>详细内容参见</strong>：<a href="./世界/太空巨构">太空巨构</a></p></blockquote><h4 id="_5-太空清除计划" tabindex="-1">5. 太空清除计划 <a class="header-anchor" href="#_5-太空清除计划" aria-label="Permalink to &quot;5. 太空清除计划&quot;">​</a></h4><p>揭示神机与维斯塔为了控制毁灭神而采取的重大太空战略决策</p><blockquote><p><strong>详细内容参见</strong>：<a href="./世界/太空清除计划">太空清除计划</a></p></blockquote><h4 id="_6-特殊地点真相" tabindex="-1">6. 特殊地点真相 <a class="header-anchor" href="#_6-特殊地点真相" aria-label="Permalink to &quot;6. 特殊地点真相&quot;">​</a></h4><p>揭示地球内重要地点（世界树、梯形神殿、红星孤儿院等）的真实历史和技术内涵</p><blockquote><p><strong>详细内容参见</strong>：<a href="./世界/特殊地点">特殊地点</a></p></blockquote><h4 id="_7-龙族真相" tabindex="-1">7. 龙族真相 <a class="header-anchor" href="#_7-龙族真相" aria-label="Permalink to &quot;7. 龙族真相&quot;">​</a></h4><p>展现龙族的真实能力、压制机制以及相关伏笔</p><blockquote><p><strong>详细内容参见</strong>：<a href="./世界/龙族真相">龙族真相</a></p></blockquote><h3 id="二、历史真相" tabindex="-1">二、历史真相 <a class="header-anchor" href="#二、历史真相" aria-label="Permalink to &quot;二、历史真相&quot;">​</a></h3><p>主线历史涵盖神造物世界观的核心历史脉络，按时间顺序分为前传、间章与正传（福瑞时代）三段：前传是人类超算纪元的背景与剧情，间章是前传与正传之间的过渡，正传是福瑞时代的中层编年史。另有《火种故事》作为黑暗时代的故事化补全。</p><ul><li><strong>正传历史</strong>：福瑞时代的中层编年史——从共同体建立到当前鹿熊冷战时代的真实脉络，是表层历史三篇（共同体时期/黑暗时代/当前时代）的真相版</li><li><strong>火种故事</strong>：《神造物·火种》故事概要——黑暗时代早期，普通生灵点燃第一簇反抗火种的故事</li><li><strong>间章历史</strong>：前传与正传之间的过渡时期历史，包含神机登神、布局新世界的关键过程</li><li><strong>前传历史</strong>：前传完整剧情线（林月视角）与前传关键机制</li><li><strong>前传超算纪元</strong>：前传背景与&quot;人物/技术志&quot;——人类超算时代的核心背景、技术路线与核心超算角色档案</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./历史/">历史真相总览</a></p></blockquote><h3 id="三、人物真相档案" tabindex="-1">三、人物真相档案 <a class="header-anchor" href="#三、人物真相档案" aria-label="Permalink to &quot;三、人物真相档案&quot;">​</a></h3><p>神明、超算与众生背后不为人知的真实档案——表层众生录中那些人物（维斯塔、拉斯塔、狼族少年、古斯塔夫、龙鹿等）的真实身份，以及从未在表层露面的存在（神机、奥克尔），都在这里。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./人物/">人物真相档案</a></p></blockquote><h2 id="与世界观其他层面的关系" tabindex="-1">与世界观其他层面的关系 <a class="header-anchor" href="#与世界观其他层面的关系" aria-label="Permalink to &quot;与世界观其他层面的关系&quot;">​</a></h2><h3 id="与表层设定的关系" tabindex="-1">与表层设定的关系 <a class="header-anchor" href="#与表层设定的关系" aria-label="Permalink to &quot;与表层设定的关系&quot;">​</a></h3><ul><li><strong>解释表象</strong>：中层设定解释表层现象背后的原因</li><li><strong>提供背景</strong>：为表层事件提供深层历史和技术背景</li><li><strong>限制认知</strong>：福瑞种族无法直接认知中层设定内容</li></ul><h3 id="与底层设定的关系" tabindex="-1">与底层设定的关系 <a class="header-anchor" href="#与底层设定的关系" aria-label="Permalink to &quot;与底层设定的关系&quot;">​</a></h3><ul><li><strong>具体应用</strong>：中层设定是底层神权体系和基底层概念的具体应用</li><li><strong>技术实现</strong>：展现底层概念在现实世界的技术实现形式</li><li><strong>有限揭示</strong>：不会直接触及神权体系的本质，而是展现其外在表现</li></ul><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><ol><li><strong>先表层后中层</strong>：建议先了解表层设定的基本框架，再探索中层真相</li><li><strong>两条路径任选</strong>： <ul><li><strong>机制路线</strong>（推荐给想先搞懂&quot;世界怎么运转&quot;的读者）：历代三神 → 地脉与魔法 → 神机谋划 → 太空巨构 → 太空清除计划 → 特殊地点 → 龙族真相</li><li><strong>以史为纲</strong>（推荐给刚读完表层历史、想逐条对答案的读者）：正传历史（与表层历史一一对照）→ 火种故事 → 间章历史 → 前传历史 → 前传超算纪元，途中遇到的世界真相条目随时跳出阅读</li></ul></li><li><strong>交叉参考</strong>：中层设定各文档之间存在密切联系，建议交叉阅读</li><li><strong>理解层次</strong>：认识到这是&quot;世界背后的真相&quot;，而非福瑞角色的认知</li></ol><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./世界/历代三神">历代三神</a></li><li><a href="./世界/地脉与魔法">地脉与魔法</a></li><li><a href="./世界/神机谋划">神机谋划</a></li><li><a href="./世界/太空巨构">太空巨构</a></li><li><a href="./世界/太空清除计划">太空清除计划</a></li><li><a href="./世界/特殊地点">特殊地点</a></li><li><a href="./世界/龙族真相">龙族真相</a></li><li><a href="./历史/">历史真相总览</a></li><li><a href="./人物/">人物真相档案</a></li><li><a href="./../表层/" class="layer-link" data-layer="表层">表层设定</a></li><li><a href="./../底层/" class="layer-link" data-layer="底层">底层设定</a></li></ul><hr>',51)])])}const q=o(e,[["render",i]]);export{c as __pageData,q as default};
